def _machine() -> tuple[str, int]:
    """Describe the machine and its usable compute threads."""
    try:
        import torch

        threads = int(torch.get_num_threads())
    except ImportError:
        import os

        threads = os.cpu_count() or 1
    return (
        f"{platform.processor() or platform.machine()} on {platform.system()}",
        threads,
    )
